using System.Diagnostics;
using System.Text.Json;
using KeyboardScreen.Core;
namespace KeyboardScreen.App.Avalonia.Platform;
public sealed class WindowsDesktopServices:IWindowsDesktopServices{
private readonly HttpClient _http=new(){Timeout=TimeSpan.FromSeconds(6)};
public async ValueTask<WeatherSettings> ResolveWeatherSettingsAsync(WeatherSettings settings,CancellationToken cancellationToken=default){if(!settings.UseAutomaticLocation)return settings;try{using var stream=await _http.GetStreamAsync("https://api.bigdatacloud.net/data/client-info",cancellationToken);using var doc=await JsonDocument.ParseAsync(stream,cancellationToken:cancellationToken);var root=doc.RootElement;double lat=root.GetProperty("location").GetProperty("latitude").GetDouble();double lon=root.GetProperty("location").GetProperty("longitude").GetDouble();string name=root.TryGetProperty("city",out var city)?city.GetString()??Loc.T("WeatherCurrentLocation"):Loc.T("WeatherCurrentLocation");return new WeatherSettings{UseAutomaticLocation=true,LocationQuery=settings.LocationQuery,Latitude=lat,Longitude=lon,AutomaticLocationName=name};}catch{return settings;}}
public bool TrySetLaunchAtStartup(bool enabled){try{string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Library","LaunchAgents");Directory.CreateDirectory(dir);string path=Path.Combine(dir,"io.github.zcat95.keyboard-screen-studio.plist");if(!enabled){if(File.Exists(path))File.Delete(path);return true;}string exe=Environment.ProcessPath??string.Empty;string plist=$"<?xml version=\"1.0\" encoding=\"UTF-8\"?><!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\"><plist version=\"1.0\"><dict><key>Label</key><string>io.github.zcat95.keyboard-screen-studio</string><key>ProgramArguments</key><array><string>{System.Security.SecurityElement.Escape(exe)}</string><string>--startup</string></array><key>RunAtLoad</key><true/></dict></plist>";File.WriteAllText(path,plist);return true;}catch{return false;}}
public void OpenFolder(string path){Directory.CreateDirectory(path);Open(path);}public void OpenUrl(string url)=>Open(url);private static void Open(string value)=>Process.Start(new ProcessStartInfo("open",value){UseShellExecute=false});public void Dispose()=>_http.Dispose();}